import React from 'react';
import { chakra, useStyleConfig } from '@chakra-ui/react';
import { ZimmProductName } from 'app/components/ui-kits/atoms/zimmProductName';
import { ZimmProductPrice } from 'app/components/ui-kits/atoms/zimmProductPrice';
import { ZimmProductDescription } from 'app/components/ui-kits/atoms/zimmProductDescription';

type ZimmProductContentProps = {
  /** The product's display name. */
  name: string;
  /**
   * Heading level for the name. Passed through rather than fixed here so the caller keeps
   * control of the page's heading outline — see `ZimmProductName`.
   */
  headingLevel: 'h1' | 'h2' | 'h3';
  /** Price, already formatted for the storefront's locale and currency by the caller. */
  price: string;
  /** Long description as authored in Business Manager. Omitted when the product has none. */
  description?: string;
};

/**
 * Molecule — the PDP text group: name, price, description.
 *
 * Model copy and the style code are deliberately *not* here. The design places them at the
 * bottom of the column, after the accordions, so the page positions them itself rather than
 * this molecule holding them and then having to unpick the order.
 */
export const ZimmProductContent = ({ name, headingLevel, price, description }: ZimmProductContentProps) => {
  const styles = useStyleConfig('ZimmProductContent', {});

  return (
    <chakra.div __css={styles} data-testid="product-content">
      <ZimmProductName name={name} as={headingLevel} />
      <ZimmProductPrice price={price} />
      <ZimmProductDescription description={description} />
    </chakra.div>
  );
};
=== CSS ===
import type { SystemStyleObject } from '@chakra-ui/react';

/**
 * Recipe for the PDP `Content` group — the DS's own 218 x 82 frame holding name, price and
 * description. Not an invented grouping.
 *
 * The 20px rhythm is a flex `gap`, not a margin on each child. Two reasons:
 *
 *  - It collapses correctly when an optional field is absent. `ZimmProductDescription` returns
 *    `null` when the product has no description, so there is no second gap to suppress. A
 *    per-child `marginBottom` would need the parent to know which children rendered, and would
 *    leave a trailing gap when the last one did not.
 *  - It cannot be out-specified by a child. An adjacent-sibling rule (`& > * + *`) was tried
 *    first and silently lost to the `margin: 0` in `zimmProductPrice.css.ts` and
 *    `zimmProductDescription.css.ts` — equal specificity, and Emotion happened to inject the
 *    child classes last. `gap` is set on the container and no child declaration can reach it.
 *    The `play` in index.stories.tsx asserts the computed value so this cannot regress.
 */

/** DS: 20px between the name, price and description rows. Exactly `spacing.l`. */
const SPACE_WITHIN_TEXT_GROUP = 'var(--zimm-scale-l)'; // 20px

export const ZimmProductContent = {
  baseStyle: {
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'flex-start',
    gap: SPACE_WITHIN_TEXT_GROUP,
  } satisfies SystemStyleObject,
};

