import type { Meta, StoryObj } from '@storybook/react-webpack5';
import React from 'react';
import { expect, within } from 'storybook/test';
import { Box } from '@chakra-ui/react';
import { ZimmProductContent } from '.';

/** The real Shopper Products payload for 8637DS241 (ZimmermannAU, 2026-08-23). */
const REAL_DESCRIPTION = [
  'The Natura Mini Dress in Blue Birds from our Spring 2024 Collection, Natura. ',
  'A long sleeve linen mini dress featuring a deep v-neckline with fitted bodice and full skirt.',
  '<br><ul><li> Linen mini dress</li><li> Long sleeves with fluted cuffs </li>',
  '<li> Crinoline hem </li><li> Invisible zip at centre back</li></ul>',
].join('');

const meta: Meta<typeof ZimmProductContent> = {
  title: 'Commerce/ZimmProductContent',
  component: ZimmProductContent,
  argTypes: {
    name: { control: 'text' },
    price: { control: 'text' },
    description: { control: 'text' },
    headingLevel: { control: 'inline-radio', options: ['h1', 'h2', 'h3'] },
  },
  decorators: [
    // The DS Content frame is 218px wide inside the info column; showing it at any other
    // width makes the wrap behaviour and the 20px rhythm unreadable.
    (Story: React.ComponentType) => (
      <Box width="218px">
        <Story />
      </Box>
    ),
  ],
};
export default meta;

type Story = StoryObj<typeof ZimmProductContent>;

export const Default: Story = {
  args: {
    name: 'Natura Mini Dress',
    headingLevel: 'h1',
    price: '$795.00',
    description: REAL_DESCRIPTION,
  },
};

export const WithoutDescription: Story = {
  name: 'Without description — rhythm collapses',
  args: {
    name: 'Natura Mini Dress',
    headingLevel: 'h1',
    price: '$795.00',
    description: undefined,
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const root = canvas.getByTestId('product-content');

    // The description atom returns null, so the group must be exactly two rows with no
    // trailing gap. A per-child marginBottom would leave 20px hanging under the price.
    await expect(canvas.queryByTestId('product-description')).not.toBeInTheDocument();
    await expect(root.children).toHaveLength(2);

    // A flex gap applies only between rendered items, so two children means exactly one gap
    // and no trailing space under the price.
    await expect(getComputedStyle(root).rowGap).toBe('20px');
  },
};

export const RhythmWithDescription: Story = {
  name: 'Rhythm — 20px between every row',
  args: {
    name: 'Natura Mini Dress',
    headingLevel: 'h1',
    price: '$795.00',
    description: '<p>A long sleeve linen mini dress.</p>',
  },
  play: async ({ canvasElement }) => {
    const root = within(canvasElement).getByTestId('product-content');
    await expect(root.children).toHaveLength(3);

    // 20px = spacing.l, asserted as a computed value so a change to the token, to the recipe,
    // or to its registration in theme/components/index.ts all surface here rather than only in
    // a visual review. It also pins down that no child can out-specify the container.
    await expect(getComputedStyle(root).rowGap).toBe('20px');
    for (const child of Array.from(root.children)) {
      await expect(getComputedStyle(child).marginTop).toBe('0px');
    }
  },
};

export const BlankDescription: Story = {
  name: 'Description present but empty — also collapses',
  // Business Manager can save the field as empty markup rather than clearing it, which is not
  // the same input as `undefined` and has to reach the same rendering.
  args: {
    name: 'Natura Mini Dress',
    headingLevel: 'h1',
    price: '$795.00',
    description: '<p></p>',
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    await expect(canvas.getByTestId('product-content').children).toHaveLength(2);
    await expect(canvas.queryByTestId('product-description')).not.toBeInTheDocument();
  },
};

