import React from 'react';
import { chakra, useStyleConfig } from '@chakra-ui/react';
import { isBlankRichText, parseRichText } from 'app/utils/richText';

type ZimmProductDescriptionProps = {
  /**
   * The product's long description, as authored in Business Manager. Parsed into React nodes
   * rather than injected as HTML — see `app/utils/richText` for why.
   */
  description?: string;
};

/**
 * Atom — the product description. Renders nothing when the product has no description, so a
 * caller can place it unconditionally.
 */
export const ZimmProductDescription = ({ description }: ZimmProductDescriptionProps) => {
  const styles = useStyleConfig('ZimmProductDescription', {});
  if (isBlankRichText(description)) return null;
  const content = parseRichText(description);

  return (
    <chakra.div __css={styles} textStyle="body2" data-testid="product-description">
      {content}
    </chakra.div>
  );
};
=== STYLECODE ===
 * The label is microcopy, so it comes from `useUiCopy()` rather than a prop: it is the same
 * string for every caller, and the hook is Context-backed app-wide static content, which
 * components.md explicitly allows a presentational leaf to read. With no UiCopyProvider
 * mounted (Storybook, a unit test) it degrades to the fallback above, so this stays renderable
 * with zero setup.
 */
export const ZimmProductStyleCode = ({ value }: ZimmProductStyleCodeProps) => {
  const styles = useMultiStyleConfig('ZimmProductStyleCode', {});
  const { t } = useUiCopy();
  if (!value) return null;

  return (
    <chakra.div __css={styles.root} textStyle="caption" data-testid="product-style-code">
      <chakra.span __css={styles.label}>{t('pdp.styleCodeLabel', LABEL_FALLBACK)}</chakra.span>
      {/*
        A real space so `textContent` — what a screen reader reads out and what a shopper
        copies — is "Style Code: 8637DS241", matching both composed page designs. It adds no
        visual width: a whitespace-only anonymous flex item is not rendered (CSS Flexbox §4),
        so the 4px `gap` in the recipe remains the only spacing.
      */}{' '}
      <chakra.span __css={styles.value}>{value}</chakra.span>
    </chakra.div>
  );
};

